def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 100:
        return 'D'

    opp_coops = 0
    for _, o in history:
        if o == 'C':
            opp_coops += 1

    if opp_coops == 0:
        return 'D'

    last_opp = history[-1][1]
    if last_opp == 'D':
        streak = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                streak += 1
            else:
                break
        if streak >= 2:
            if streak >= 3 and history[-1][0] == 'C':
                return 'D'
            elif streak >= 3:
                return 'C'
            else:
                return 'D'
        else:
            if opp_coops * 5 >= n * 4:
                return 'C'
            else:
                return 'D'
    else:
        return 'C'
